  return {
    commitSha: resolved.commitSha,
    checkpointId,
    commitDiffPatch: resolved.commitDiffPatch,
    checkpointResolution: 'direct',
    includedCheckpoints: resolved.includedCheckpoints,
    checkpointSelectionMode: resolved.checkpointSelectionMode,
  };
}

